import type { Messages } from "@synwevo/ui/i18n-core";

/** Refusals the Synwevo Docs server can give a person in the workbench, keyed by the server's
 *  own sentence (CI-86). `refusalMessages` are matched exactly (a refusal reaches the reader as
 *  the catalogued sentence) or are the sources `lib/refusals.ts` words from a refusal's `detail`.
 *  `refusalPatterns` are server sentences with values in them — a file name, a page, a limit —
 *  raised by the format engines, which have no structured detail to carry them: the value is
 *  read back out of the sentence by its shape. `{reason}` is itself a server sentence and is
 *  presented the same way; every other parameter is data and stays verbatim.
 *  `tests/refusals.test.ts` reads the server's refusals and holds this file to them. */
