  "模板没有第 {page} 页": { en: "The template has no page {page}.", "zh-Hant": "模板沒有第 {page} 頁" },
  "字段「{name}」区域内仍有无法移除的文字：{text}": { en: "Text that cannot be removed remains in the region of the field “{name}”: {text}", "zh-Hant": "欄位「{name}」區域內仍有無法移除的文字：{text}" },
  "有 {count} 个文字只部分位于框内，它们不会被移除：{text}": { en: { one: "{count} character lies only partly inside the box and will not be removed: {text}", other: "{count} characters lie only partly inside the box and will not be removed: {text}" }, "zh-Hant": "有 {count} 個文字只部分位於框內，它們不會被移除：{text}" },
  "模板中找不到表单字段「{name}」": { en: "The template has no form field “{name}”.", "zh-Hant": "模板中找不到表單欄位「{name}」" },
  "字段「{name}」内容过长，缩小到 {size} 号字仍无法放入区域": { en: "The content of the field “{name}” is too long: even at font size {size} it does not fit in its region.", "zh-Hant": "欄位「{name}」內容過長，縮小到 {size} 號字仍無法放入區域" },
